export type MemberCategory =
  | 'Doctor'
  | 'Banker'
  | 'Business'
  | 'Engineer'
  | 'Lawyer'
  | 'Educator'
  | 'Other';

export type Member = {
  id: string;
  name: string;
  nameBn?: string;
  category: MemberCategory;
  specialty: string;
  organization: string;
  location?: string;
  bloodGroup?: string;
  phone: string;
  photo?: string;
  initials: string;
  bio?: string;
};

const initialsOf = (name: string) =>
  name
    .replace(/^(Dr\.?|Mr\.?|Mrs\.?|Ms\.?|Md\.?)\s+/i, '')
    .split(/\s+/)
    .slice(0, 2)
    .map((p) => p[0]?.toUpperCase() ?? '')
    .join('');

const m = (data: Omit<Member, 'initials'>): Member => ({
  ...data,
  initials: initialsOf(data.name)
});

